  async function archivePage(){const archive=await repo.archives.list(),cutoff=new Date(archive.cutoff),values=archive.items||[];await shell(`<section class="page archive-page"><div class="page-heading"><div><h1>业务需求归档</h1><p>发布截止当前超过六个月的需求会自动归档，按项目与版本统一留存。</p></div><span class="archive-cutoff">自动归档截止：${esc(cutoff.toLocaleDateString('zh-CN'))}</span></div><section class="archive-summary"><div><span>已归档需求</span><strong>${archive.total}</strong></div><div><span>项目 / 版本编组</span><strong>${archive.groupCount}</strong></div><p>归档资格、身份可见范围和项目版本编组均由服务端统一计算。</p></section><div class="archive-groups">${values.length?values.map(group=>`<section class="archive-group"><header class="archive-group__head"><div><span class="archive-group__eyebrow">项目 / 版本</span><h2>${esc(group.projectName)} <i>/</i> ${esc(group.version)}</h2><span class="archive-group__release-date">版本发布时间：${esc(group.versionReleaseDate||'待维护')}</span></div><span class="archive-group__count">业务需求数：${group.requirements.length}</span></header><div class="archive-table-wrap"><table class="archive-table"><thead><tr><th>需求编号</th><th>需求简述</th><th>需求来源</th><th>产品Owner</th><th>发布日期</th><th>归档状态</th><th></th></tr></thead><tbody>${group.requirements.map(r=>`<tr><td>${esc(r.code)}</td><td><b>${esc(r.title)}</b></td><td>${esc(r.source||'-')}</td><td>${productOwnerLabel(r.productOwnerName)}</td><td>${esc(r.releaseDate)}</td><td><span class="archive-status">已归档</span></td><td><button class="btn text" data-archive-detail="${r.id}">查看</button></td></tr>`).join('')}</tbody></table></div></section>`).join(''):'<section class="archive-empty"><span>暂无可归档的业务需求</span><p>完成发布后手动归档，或发布日期满六个月的需求会出现在这里。</p></section>'}</div></section>`);document.querySelectorAll('[data-archive-detail]').forEach(b=>b.onclick=()=>{st.id=b.dataset.archiveDetail;st.view='detail';render()})}
